import type { NetworkAssetsDefinition } from './NetworkAssetsDefinition';

export const generateNetworkAssetsSource = (definition: NetworkAssetsDefinition): string => {
    const family = definition.family;
    const familyType = family[0].toUpperCase() + family.slice(1);

    const assetSymbolType = [
        `${familyType}NetworkSymbol`,
        ...definition.extraSymbols.map(symbol => `'${symbol}'`),
    ].join(' | ');

    return `
        // !!! IMPORTANT: This file is autogenerated !!!
        import type {
            NetworkAssetsModule,
            NetworkIconAsset,
        } from '@trezor/network-assets-types';
        import {
            type ${familyType}NetworkSymbol,
            supported${familyType}Networks,
        } from '@trezor/network-${family}-types';

        import { ${family}CryptoIcons } from './cryptoIcons';
        import { ${family}NetworkIcons } from './networkIcons';

        export type ${familyType}AssetSymbol = ${assetSymbolType};

        // Keep SVG loading lazy so registering assets does not load their files.
        const icons: Record<${familyType}AssetSymbol, NetworkIconAsset> = {
            ${definition.symbols
                .map(
                    ({ symbol, coin, network }) => `${symbol}: {
                        getIcons: () => ({
                            coin: ${family}CryptoIcons.${coin}.getIcon(),
                            network: ${family}NetworkIcons.${network}.getIcon(),
                        }),
                        getIconPaths: () => ({
                            coin: ${family}CryptoIcons.${coin}.getIconPath(),
                            network: ${family}NetworkIcons.${network}.getIconPath(),
                        }),
                    }`,
                )
                .join(',')}
        };

        export const ${family}Assets: NetworkAssetsModule<${familyType}AssetSymbol> = {
            regenerateIcons: deps => deps.regenerateNetworkIcons({
                family: '${family}',
                supportedNetworks: supported${familyType}Networks,
                icons,
            }),
            getIcons: symbol => icons[symbol].getIcons(),
            getIconPaths: symbol => icons[symbol].getIconPaths(),
        };
    `;
};
